import hashlib
import json
from math import gcd
from itertools import product


def band(entries, eps):
    """Naive band: enumerate every (lo, hi) endpoint pair explicitly."""
    best = None  # (mass, lo, hi)
    values = sorted({v for v, _w in entries})
    for lo in values:
        for hi in values:
            if hi < lo:
                continue
            if 1000000 * (hi - lo) > eps * hi:
                continue
            mass = sum(w for v, w in entries if lo <= v <= hi)
            if best is None or mass > best[0] or (mass == best[0] and (lo < best[1] or (lo == best[1] and hi < best[2]))):
                best = (mass, lo, hi)
    mass, lo, hi = best
    total = sum(v * w for v, w in entries if lo <= v <= hi)
    return total // mass, mass


def whash(seed, r, t, a, b):
    d = ("%d:%d:%d:%d:%d" % (seed, r, t, a, b)).encode("ascii")
    return int.from_bytes(hashlib.sha256(d).digest()[:8], "big")


