            flows.append((v, u))
        self.flows = sorted(flows)
        cap = {}
        for (u, v, c) in self.links:
            cap[(u, v)] = cap[(v, u)] = c
        for e in self.ext:
            cap[(-1, e)] = cap[(e, -1)] = self.nodes[e]["external_capacity"]
        self.cap = cap
        keys = {}
        self.flow_keys = {}
        for f in self.flows:
            a, b = f
            if a == -1:
                ks = ["low_%s_origination" % self.name[b]]
            elif b == -1:
                ks = ["low_%s_termination" % self.name[a]]
            else:
                ks = ["low_%s_egress_to_%s" % (self.name[a], self.name[b]),
                      "low_%s_ingress_from_%s" % (self.name[b], self.name[a])]
            self.flow_keys[f] = ks
            for k in ks:
                keys[k] = f
        self.key_flow = keys
        self.all_keys = sorted(keys)
        self.counters = {k: None for k in self.all_keys}  # value or None (missing)
        self.demands = {(s, d): 0 for s in self.ext for d in self.ext if s != d}
        self.paths = None
        self.cache = {}          # key -> publication
        self.recency = {}        # key -> stamp
        self.stamp = 0
        self.snaps = {}

    # ---- patch
    def patch(self, ev):
        if set(ev.keys()) != {"op", "demands", "counters"}:
            return {"op": "patch", "accepted": False}
        dem, cnt = ev["demands"], ev["counters"]
        if type(dem) is not list or type(cnt) is not dict:
            return {"op": "patch", "accepted": False}
        seen = set()
        du, cu = [], []
        for e in dem:
            if not isinstance(e, list) or len(e) != 3:
                return {"op": "patch", "accepted": False}
            if not all(type(x) is int for x in e):
                return {"op": "patch", "accepted": False}
            s, d, v = e
            if s == d or s not in self.ext or d not in self.ext:
                return {"op": "patch", "accepted": False}
            if (s, d) in seen:
                return {"op": "patch", "accepted": False}
            seen.add((s, d))
            if not (0 <= v <= 10 ** 9):
                return {"op": "patch", "accepted": False}
            du.append((s, d, v))
        for k, cell in cnt.items():
            if k not in self.key_flow:
                return {"op": "patch", "accepted": False}
            if cell is None:
                cu.append((k, None))
                continue
            if type(cell) is not dict:
                return {"op": "patch", "accepted": False}
            if "perturbed" not in cell:
                return {"op": "patch", "accepted": False}
            if not set(cell) <= {"perturbed", "ground_truth", "corrected", "confidence"}:
                return {"op": "patch", "accepted": False}
            p = cell["perturbed"]
            if p is None:
                cu.append((k, None))
                continue
            if type(p) is not int:
                return {"op": "patch", "accepted": False}
            if not (0 <= p <= self.cap[self.key_flow[k]]):
                return {"op": "patch", "accepted": False}
            cu.append((k, p))
        for (s, d, v) in du:
            self.demands[(s, d)] = v
        for (k, v) in cu:
            self.counters[k] = v
        return {"op": "patch", "accepted": True}

