            self.paths = None
        else:
            bundles = {}
            for sn, db in raw.items():
                si = self.id_by_name[sn]
                for dn, items in db.items():
                    di = self.id_by_name[dn]
                    bundles[(si, di)] = [(tuple(it["path"]), it["weight"]) for it in items]
            self.paths = bundles
        return {"op": "routes", "accepted": True}

