                    for (s, d), items in self.paths.items():
                        dem = self.demands[(s, d)]
                        for (path, w) in items:
                            for x, y in zip(path, path[1:]):
                                hop = (self.id_by_name[x], self.id_by_name[y])
                                if hop == f:
                                    total += dem * w
                    internal[f] = total // 1000
                else:
                    internal[f] = ext[f]
