    def repair_pub(self):
        s = self.settings
        eps = s["epsilon"]
        T = s["trials"]
        seed = s["seed"]
        internal, ext = self.predict()
        pools = {f: self.pool_of(f, internal, ext) for f in self.flows}

        def sample(f, r, t, fixed):
            if f in fixed:
                return fixed[f]
            pool = pools[f]
            if not pool:
                return 0
            return pool[whash(seed, r, t, f[0], f[1]) % len(pool)]

        routers = sorted({x for f in self.flows for x in f if x != -1})

        def real_ends(f):
            return [x for x in f if x != -1]

        def incident(r):
            return [f for f in self.flows if r in f]

        def router_item(f, r, fixed):
            rems = []
            for t in range(T):
                insum = 0
                outsum = 0
                for g in incident(r):
                    v = sample(g, r, t, fixed)
                    if g[1] == r:
                        insum += v
                    if g[0] == r:
                        outsum += v
                # target's own sampled value cancels from the remainder
                if f[1] == r and f[0] != r:  # incoming
                    rem = outsum - (insum - sample(f, r, t, fixed))
                else:  # outgoing
                    rem = insum - (outsum - sample(f, r, t, fixed))
                if rem < 0:
                    rem = 0
                if rem > self.cap[f]:
                    rem = self.cap[f]
                rems.append((rem, 1))
            return band(rems, eps)

        def flow_item(f, fixed):
            entries = [(v, T) for v in pools[f]]
            for r in real_ends(f):
                rep, mass = router_item(f, r, fixed)
                entries.append((rep, mass))
            return band(entries, eps)

        fixed = {}
        order = []
        values = {}
        conf = {}
        remaining = set(self.flows)
        while remaining:
            best = None
            for f in sorted(remaining):
                c, sup = flow_item(f, fixed)
                if best is None or sup > best[1] or (sup == best[1] and f < best[0]):
                    best = (f, sup, c)
            f, sup, c = best
            values[f] = c
            g = gcd(sup, T)
            conf[f] = (sup // g, T // g)
            order.append(list(f))
            fixed[f] = c
            remaining.discard(f)
        links = [list(f) + [values[f], conf[f][0], conf[f][1]] for f in self.flows]
        counters = {}
        for f in self.flows:
            for k in self.flow_keys[f]:
                counters[k] = {"corrected": values[f], "confidence": [conf[f][0], conf[f][1]]}
        return links, order, counters

    def cache_key(self):
        ckey = tuple((k, self.counters[k]) for k in self.all_keys)
        dkey = tuple(sorted(self.demands.items()))
        rkey = None
        if self.paths is not None:
            entries = []
            for (s, d), items in self.paths.items():
                for (path, w) in items:
                    entries.append((self.name[s], self.name[d], path, w))
            rkey = tuple(sorted(entries))
        s = self.settings
        return (ckey, dkey, rkey, s["seed"], s["trials"], s["epsilon"])

    def do_repair(self, ev):
        key = self.cache_key()
        hit = key in self.cache
        if hit:
            links, order, counters = self.cache[key]
            self.stamp += 1
            self.recency[key] = self.stamp
        else:
            links, order, counters = self.repair_pub()
            self.cache[key] = (links, order, counters)
            self.stamp += 1
            self.recency[key] = self.stamp
            if self.settings["cache_slots"] < len(self.cache):
                # evict least recently repaired
                victim = min(self.cache, key=lambda k: self.recency[k])
                del self.cache[victim]
                del self.recency[victim]
        self.snaps[ev["id"]] = (json.loads(json.dumps(links)),
                               json.loads(json.dumps(order)),
                               json.loads(json.dumps(counters)))
        return {"op": "repair", "id": ev["id"], "cache_hit": hit,
                "links": json.loads(json.dumps(links)),
                "order": json.loads(json.dumps(order)),
                "counters": json.loads(json.dumps(counters))}

    def do_validate(self, ev):
        snap = self.snaps.get(ev["id"])
        if snap is None:
            return {"op": "validate", "id": ev["id"], "checked": 0,
                    "passed": 0, "consistent": None, "failed": []}
        links, order, counters = snap
        s = self.settings
        cnum, cden = s["cutoff"]
        gnum, gden = s["gamma"]
        internal, ext = self.predict()
        checked = passed = 0
        failed = []
        for row in links:
            (a, b, value, num, den) = row
            if num * cden < cnum * den:
                continue
            f = (a, b)
            if a != -1 and b != -1:
                if internal is None:
                    continue
                pred = internal[f]
            else:
                pred = ext[f]
            X = value * 1000000
            Y = pred * (1000000 - s["bias"])
            ok = 1000000 * abs(X - Y) <= s["tau"] * max(X, Y)
            cells = self.flow_keys[f]
            checked += len(cells)
            if ok:
                passed += len(cells)
            else:
                failed.extend(cells)
        failed.sort()
        consistent = None if checked == 0 else (passed * gden >= gnum * checked)
        return {"op": "validate", "id": ev["id"], "checked": checked,
                "passed": passed, "consistent": consistent, "failed": failed}

    def apply(self, ev):
        if ev["op"] == "patch":
            return self.patch(ev)
        if ev["op"] == "routes":
            return self.routes(ev)
        if ev["op"] == "repair":
            return self.do_repair(ev)
        if ev["op"] == "validate":
            return self.do_validate(ev)
        raise ValueError("unknown op")


