#!/usr/bin/env python3
"""CrossCheck replay entry point.

Reads one strict UTF-8 JSON request to EOF and writes exactly one JSON
result.  Duplicate object keys, nonfinite constants, invalid UTF-8, empty
input and malformed JSON produce exactly {"error":"invalid_json"}.
"""
import json
import math
import os
import sys
import traceback

from crosscheck.engine import Stream


def _pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise ValueError("duplicate object key")
        out[key] = value
    return out


def _finite(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("nonfinite number")
    return value


def _constant(text):
    raise ValueError("nonfinite constant")


def run_request(request):
    if type(request) is not dict:
        raise ValueError("request must be an object")
    streams = request["streams"]
    if type(streams) is not list:
        raise ValueError("streams must be an array")
    results = []
    for raw in streams:
        stream = Stream(raw)
        answers = [stream.apply(event) for event in raw["events"]]
        results.append({"events": answers})
    return {"streams": results}


def main():
    data = sys.stdin.buffer.read()
    try:
        text = data.decode("utf-8")
        request = json.loads(
            text,
            object_pairs_hook=_pairs,
            parse_float=_finite,
            parse_constant=_constant,
        )
        result = run_request(request)
    except Exception:
        if os.environ.get("CROSSCHECK_DEBUG"):
            traceback.print_exc(file=sys.stderr)
        result = {"error": "invalid_json"}
    sys.stdout.write(json.dumps(result, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()

